import pandas as pd

def salaries_difference(salaries: pd.DataFrame) -> pd.DataFrame:
    eng = salaries[salaries["department"] == "Engineering"]["salary"].max()
    mkt = salaries[salaries["department"] == "Marketing"]["salary"].max()
    diff = abs(eng - mkt)
    return pd.DataFrame([{"salary_diff": diff}])
